12	// GitleaksFinding represents a single finding from Gitleaks
13	type GitleaksFinding struct {
14		RuleID      string `json:"RuleID"`
15		Description string `json:"Description"`
16		StartLine   int    `json:"StartLine"`
17		EndLine     int    `json:"EndLine"`
18		StartColumn int    `json:"StartColumn"`
19		EndColumn   int    `json:"EndColumn"`
20		Match       string `json:"Match"`
21		Secret      string `json:"Secret"`
22		File        string `json:"File"`
23		Fingerprint string `json:"Fingerprint,omitempty"`
24		Commit      string `json:"Commit,omitempty"`
25		Author      string `json:"Author,omitempty"`
26		Email       string `json:"Email,omitempty"`
27		Date        string `json:"Date,omitempty"`
28		Message     string `json:"Message,omitempty"`
29	}
30	
31	// gitleaksSecretsFound is the exit code Gitleaks uses to say it found
32	// something. It is a result, not a failure.
33	const gitleaksSecretsFound = 1
34	
35	// gitleaksArgs builds the invocation. Gitleaks writes its report to a path
36	// rather than to stdout, so the report path is redirected at the process's own
37	// stdout — which is a different pseudo-file inside a container.
38	func gitleaksArgs(target string, source ToolSource, image string, history bool, configPath string) toolCmd {
39		appendOptions := func(args []string) []string {
40			// History is the expensive mode, so it is opted into by dropping
41			// --no-git rather than by adding a flag.
42			if !history {
43				args = append(args, "--no-git")
44			}
45			if configPath != "" {
46				args = append(args, "--config", configPath)
47			}
48			return args
49		}
50	
51		if source == ToolSourceDocker {
52			if image == "" {
53				image = DefaultGitleaksImage
54			}
55			args := []string{
56				"run", "--rm",
57				"-v", target + ":" + containerScanPath + ":ro",
58				image,
59				"detect",
60				"--source", containerScanPath,
61				"--gitleaks-ignore-path", containerScanPath,
62				"--report-format", "json",
63				"--report-path", "/dev/fd/1",
64			}
65			return toolCmd{Name: "docker", Args: appendOptions(args)}
66		}
67	
68		args := []string{
69			"detect",
70			"--source", target,
71			"--gitleaks-ignore-path", target,
72			"--report-format", "json",
73			"--report-path", "/dev/stdout",
74		}
75		return toolCmd{Name: "gitleaks", Args: appendOptions(args)}
76	}
77	
78	// RunGitleaks executes Gitleaks and returns findings.
79	// progressFn is an optional callback called with each stderr line.
80	func RunGitleaks(ctx context.Context, target string, source ToolSource, image string, history bool, configPath string, progressFn func(string)) ([]Finding, error) {
81		stdout, err := runner.Run(ctx, gitleaksArgs(target, source, image, history, configPath), progressFn)
82		if err != nil && len(stdout) == 0 {
83			// Exit 1 with no report means it ran and found nothing; any other
84			// non-zero exit, or a process that never ran, is a genuine failure.
85			var exit *exitError
86			if !errors.As(err, &exit) || exit.Code != gitleaksSecretsFound {
87				return nil, fmt.Errorf("gitleaks failed: %w", err)
88			}
89		}
90	
91		if len(stdout) == 0 {
92			return []Finding{}, nil
93		}
94		return parseGitleaksOutput(stdout)
95	}
96	
97	// parseGitleaksOutput parses Gitleaks JSON output into findings
98	func parseGitleaksOutput(data []byte) ([]Finding, error) {
99		var gitleaksFindings []GitleaksFinding
100		if err := json.Unmarshal(data, &gitleaksFindings); err != nil {
101			return nil, fmt.Errorf("failed to parse gitleaks output: %w", err)
102		}
103	
104		findings := make([]Finding, 0, len(gitleaksFindings))
105	
106		for _, gf := range gitleaksFindings {
107			findings = append(findings, Finding{
108				ID:          gf.RuleID,
109				Title:       fmt.Sprintf("Secret detected: %s", gf.RuleID),
110				Description: gf.Description,
111				Severity:    SeverityHigh, // Secrets are always high severity
112				Source:      "gitleaks",
113				File:        gf.File,
114				Line:        gf.StartLine,
115				Match:       maskSecret(gf.Secret),
116				Fingerprint: gf.Fingerprint,
117			})
118		}
119	
120		return findings, nil
121	}
122	
123	// GetGitleaksCommand returns the command that would be executed, for display
124	// and logging. It is built by the same builder as the executed command, so the
125	// two cannot drift apart.
126	func GetGitleaksCommand(target string, source ToolSource, image string, history bool, configPath string) string {
127		return gitleaksArgs(target, source, image, history, configPath).String()
128	}
