130	// AddToGitleaksIgnore adds a finding to the .gitleaksignore file in the target directory
131	// Returns nil if already present (silently skips duplicates)
132	func AddToGitleaksIgnore(targetDir string, finding Finding) (err error) {
133		ignorePath := targetDir + "/.gitleaksignore"
134	
135		// Use the fingerprint as the ignore entry (gitleaks native format)
136		entry := finding.Fingerprint
137		if entry == "" {
138			// Fallback: build fingerprint manually
139			entry = fmt.Sprintf("%s:%s:%d", finding.File, finding.ID, finding.Line)
140		}
141	
142		// Check if entry already exists
143		if existingContent, readErr := os.ReadFile(ignorePath); readErr == nil {
144			if strings.Contains(string(existingContent), entry) {
145				// Already present, silently skip
146				return nil
147			}
148		}
149	
150		// Open file in append mode, create if doesn't exist
151		f, err := os.OpenFile(ignorePath, os.O_APPEND|os.O_CREATE|os.O_WRONLY, 0644)
152		if err != nil {
153			return fmt.Errorf("failed to open .gitleaksignore: %w", err)
154		}
155		defer func() {
156			if cerr := f.Close(); cerr != nil && err == nil {
157				err = fmt.Errorf("failed to close .gitleaksignore: %w", cerr)
158			}
159		}()
160	
161		if _, err := f.WriteString(entry + "\n"); err != nil {
162			return fmt.Errorf("failed to write to .gitleaksignore: %w", err)
163		}
164	
165		return nil
166	}
